import React from "react";

export default function About() {
  return (
    <div className="about-page">

      {/* HERO INTRO */}
      <div className="about-hero">
        <h1>
          About <span>Me</span>
        </h1>

        <p className="tagline">
          IT Developer focused on building intelligent, user-first digital systems.
        </p>
      </div>

      {/* MAIN GRID */}
      <div className="about-grid">

        {/* LEFT STORY */}
        <div className="card glass">

          <h2>Who I Am</h2>

          <p>
            I am an Information Technology student passionate about building
            practical, real-world solutions using software and modern technologies.
            I enjoy understanding how systems work at a deeper level and turning
            ideas into clean, scalable, and efficient applications.
          </p>

          <p>
            My approach is simple — break problems down, think logically, and
            build step by step. I learn best by building projects and continuously
            improving through hands-on experience.
          </p>

          <div className="principles">
            <span>⚡ Problem Solver</span>
            <span>🧠 Logical Thinker</span>
            <span>🚀 Fast Learner</span>
          </div>
        </div>

        {/* RIGHT SIDE */}
        <div className="right-stack">

          {/* EDUCATION */}
          <div className="card glass">
            <h2>🎓 Education</h2>

            <div className="timeline">
              <div>
                <h4>B.Tech – Information Technology</h4>
                <p className="muted">Panimalar Engineering College</p>
                <span className="badge">2023 – 2027</span>
              </div>
            </div>

            <p className="small">
              Focused on software development, system design, and hands-on project building.
            </p>
          </div>

          {/* SKILLS */}
          <div className="card glass">
            <h2>⚡ Core Skills</h2>

            <div className="chips">
              <span>Java</span>
              <span>React</span>
              <span>Spring Boot</span>
              <span>MySQL</span>
              <span>HTML</span>
              <span>CSS</span>
              <span>JavaScript</span>
              <span>UI/UX</span>
              <span>AI Basics</span>
            </div>
          </div>

          {/* CURRENTLY BUILDING */}
          <div className="card highlight">
            <h2>🚧 Currently Building</h2>
            <ul>
              <li>EnergyPulse Smart Dashboard (IoT + AI)</li>
              <li>Full Stack Portfolio Systems</li>
              <li>React-based UI Prototypes</li>
            </ul>
          </div>

        </div>
      </div>

      {/* HIGHLIGHTS */}
      <div className="highlights">
        <div>
          <h3>5+</h3>
          <p>Projects Built</p>
        </div>

        <div>
          <h3>10+</h3>
          <p>Technologies</p>
        </div>

        <div>
          <h3>2+</h3>
          <p>Core Domains</p>
        </div>
      </div>

      {/* STYLE */}
      <style>{`

        .about-page {
          min-height: 100vh;
          padding: 60px 10%;
          font-family: "Poppins", sans-serif;
          background: radial-gradient(circle at top, #0f172a, #050816);
          color: white;
        }

        /* HERO */
        .about-hero h1 {
          font-size: 46px;
          margin-bottom: 8px;
        }

        .about-hero span {
          color: #38BDF8;
        }

        .tagline {
          color: #94a3b8;
          margin-bottom: 40px;
        }

        /* GRID */
        .about-grid {
          display: grid;
          grid-template-columns: 1.3fr 1fr;
          gap: 30px;
        }

        /* CARDS */
        .card {
          padding: 22px;
          border-radius: 16px;
        }

        .glass {
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.15);
          backdrop-filter: blur(10px);
        }

        h2 {
          color: #38BDF8;
          margin-bottom: 10px;
        }

        p {
          color: #cbd5e1;
          line-height: 1.7;
        }

        .muted {
          color: #94a3b8;
        }

        .small {
          font-size: 13px;
          margin-top: 10px;
        }

        /* PRINCIPLES */
        .principles {
          display: flex;
          gap: 10px;
          margin-top: 15px;
          flex-wrap: wrap;
        }

        .principles span {
          background: rgba(56,189,248,0.1);
          padding: 6px 10px;
          border-radius: 20px;
          font-size: 12px;
        }

        /* TIMELINE */
        .badge {
          display: inline-block;
          margin-top: 6px;
          padding: 3px 8px;
          font-size: 11px;
          border-radius: 8px;
          background: rgba(56,189,248,0.15);
          color: #38BDF8;
        }

        /* SKILLS */
        .chips {
          display: flex;
          flex-wrap: wrap;
          gap: 8px;
          margin-top: 10px;
        }

        .chips span {
          padding: 6px 10px;
          border-radius: 14px;
          font-size: 12px;
          background: rgba(255,255,255,0.06);
          border: 1px solid rgba(255,255,255,0.08);
        }

        /* CURRENTLY BUILDING */
        .highlight {
          background: linear-gradient(135deg, rgba(56,189,248,0.1), rgba(99,102,241,0.1));
          border: 1px solid rgba(56,189,248,0.2);
        }

        .highlight ul {
          margin-top: 10px;
          padding-left: 18px;
          color: #cbd5e1;
        }

        /* RIGHT STACK */
        .right-stack {
          display: flex;
          flex-direction: column;
          gap: 20px;
        }

        /* HIGHLIGHTS */
        .highlights {
          margin-top: 50px;
          display: flex;
          justify-content: space-between;
          text-align: center;
        }

        .highlights div {
          flex: 1;
        }

        .highlights h3 {
          color: #38BDF8;
          font-size: 28px;
        }

        .highlights p {
          color: #94a3b8;
        }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .about-grid {
            grid-template-columns: 1fr;
          }

          .highlights {
            flex-direction: column;
            gap: 20px;
          }
        }

      `}</style>

    </div>
  );
}
